<?php require_once 'auth.php'; if(!empty($_SESSION['admin_user'])){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $pdo=db(); $email=trim($_POST['email']??''); $pass=$_POST['password']??''; if($pdo){try{$q=$pdo->prepare('SELECT id,name,email,password_hash,role,active FROM users WHERE email=? LIMIT 1');$q->execute([$email]);$u=$q->fetch(PDO::FETCH_ASSOC);if($u&&$u['active']&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['admin_user']=$u;header('Location: index.php');exit;}}catch(Throwable $e){}} $error='Email hoặc mật khẩu không chính xác.'; } ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đăng nhập · IMA PRIME Admin</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Be+Vietnam+Pro:wght@300;400;500;600&family=Newsreader:opsz,wght@6..72,300;6..72,400&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/admin.css"></head><body class="login-body"><main class="login-card"><a class="login-brand" href="../index.php">IMA <em>PRIME</em></a><div class="login-label">QUẢN TRỊ NỘI DUNG</div><h1>Chào mừng trở lại.</h1><p>Đăng nhập để quản lý nội dung website.</p><?php if($error): ?><div class="notice error"><?=$error?></div><?php endif ?><form method="post"><label>Email<input required type="email" name="email" autocomplete="email" autofocus></label><label>Mật khẩu<input required type="password" name="password" autocomplete="current-password"></label><button class="admin-button">Đăng nhập</button></form><a class="login-back" href="../index.php">← Quay lại website</a></main></body></html>
